INSERT INTO `dish` (`id`, `name`, `category_id`, `price`, `image`, `description`, `status`, `create_time`, `update_time`, `create_user`, `update_user`) VALUES
  (1, '麻婆豆腐', 1, 26, 'http://localhost:8080/menu-images/mapo-tofu.jpg', '嫩豆腐与肉末裹满红油，花椒麻香，经典川味下饭菜。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (2, '宫保鸡丁', 1, 32, 'http://localhost:8080/menu-images/kung-pao-chicken.jpg', '鸡丁配花生与干辣椒，咸鲜微甜，入口酥香。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (3, '干香辣子鸡', 1, 38, 'http://localhost:8080/menu-images/spicy-chicken.jpg', '鸡块炸至金黄，配干辣椒、花椒大火炒香。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (4, '糖醋咕噜肉', 2, 36, 'http://localhost:8080/menu-images/sweet-sour-pork.jpg', '酥炸猪肉裹酸甜酱汁，外酥里嫩。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (5, '秘制红烧肉', 2, 42, 'http://localhost:8080/menu-images/braised-pork.jpg', '厚切五花肉慢炖收汁，酱香浓郁，软糯入味。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (6, '香辣烤茄子', 2, 22, 'http://localhost:8080/menu-images/roasted-eggplant.jpg', '茄子烤至软嫩，配香辣调味汁，鲜香下饭。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (7, '皮蛋嫩豆腐', 3, 18, 'http://localhost:8080/menu-images/century-egg-tofu.jpg', '嫩豆腐搭配皮蛋、葱花与酱汁，清爽开胃。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (8, '蒜香空心菜', 3, 18, 'http://localhost:8080/menu-images/water-spinach.jpg', '空心菜大火快炒，保留清脆口感与蒜香。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (9, '干煸四季豆', 3, 24, 'http://localhost:8080/menu-images/green-beans.jpg', '四季豆煸至起皱，干香微辣，越嚼越香。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (10, '牛油果绿蔬沙拉', 3, 28, 'http://localhost:8080/menu-images/green-salad.jpg', '牛油果、黄瓜与时蔬搭配，清爽轻盈。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (11, '芝麻拍黄瓜', 3, 16, 'http://localhost:8080/menu-images/cucumber-salad.jpg', '脆嫩黄瓜配红椒与芝麻，酸爽开胃。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (12, '现蒸白米饭', 4, 3, 'http://localhost:8080/menu-images/white-rice.jpg', '现蒸热米饭，一碗约200克，搭配热菜更满足。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (13, '招牌蛋炒饭', 4, 18, 'http://localhost:8080/menu-images/egg-fried-rice.jpg', '米饭大火翻炒，蛋香与葱香交融，粒粒分明。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (14, '红烧牛肉面', 4, 32, 'http://localhost:8080/menu-images/beef-noodles.jpg', '浓香牛肉汤底配牛肉块、面条和青菜，一碗暖心。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (15, '牛肉溏心蛋粉丝', 4, 30, 'http://localhost:8080/menu-images/glass-noodles.jpg', '牛肉、溏心蛋与粉丝搭配清香汤底，鲜香顺口。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (16, '时蔬炒面', 4, 22, 'http://localhost:8080/menu-images/vegetable-noodles.jpg', '面条配彩椒、菌菇与时蔬，酱香浓郁。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (17, '鲜虾时蔬饭', 4, 35, 'http://localhost:8080/menu-images/shrimp-rice.jpg', '鲜虾搭配彩蔬与米饭，一盘兼顾荤素。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (18, '香酥鸡块饭', 4, 28, 'http://localhost:8080/menu-images/chicken-rice.jpg', '香酥鸡块盖在米饭上，配香草点缀，酥香满足。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (19, '红油鲜肉水饺', 5, 26, 'http://localhost:8080/menu-images/dumplings.jpg', '鲜肉水饺配香辣红油、葱花，约10只一份。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (20, '鲜肉小笼包', 5, 25, 'http://localhost:8080/menu-images/xiaolongbao.jpg', '鲜肉小笼包现蒸出笼，一笼约8只。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (21, '香酥炸鸡翅', 5, 26, 'http://localhost:8080/menu-images/chicken-wings.jpg', '外皮金黄酥脆，内里鲜嫩多汁，约4只一份。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (22, '金黄薯条', 5, 15, 'http://localhost:8080/menu-images/fries.jpg', '粗细适中的薯条炸至金黄，外酥内软，约150克。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (23, '香脆素春卷', 5, 18, 'http://localhost:8080/menu-images/spring-rolls.jpg', '薄皮包裹蔬菜馅，炸至金黄酥脆，约4只一份。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (24, '鲜虾蔬菜米纸卷', 5, 24, 'http://localhost:8080/menu-images/fresh-spring-rolls.jpg', '米纸包裹虾仁与蔬菜，搭配蘸汁，约3卷一份。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (25, '香草蒜香虾', 2, 39, 'http://localhost:8080/menu-images/garlic-shrimp.jpg', '鲜虾配香草与蒜香调味，鲜嫩弹牙。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (26, '香浓菌菇汤', 6, 18, 'http://localhost:8080/menu-images/mushroom-soup.jpg', '菌菇熬煮成浓汤，配香草点缀，一份约300毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (27, '罗勒番茄浓汤', 6, 16, 'http://localhost:8080/menu-images/tomato-soup.jpg', '番茄熬出自然酸甜，搭配罗勒，一份约300毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (28, '冰爽可乐', 7, 8, 'http://localhost:8080/menu-images/cola.jpg', '经典碳酸可乐，一杯约350毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (29, '手作柠檬茶', 7, 12, 'http://localhost:8080/menu-images/lemon-tea.jpg', '清香茶底配柠檬与薄荷，一杯约450毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (30, '鲜榨橙汁', 7, 16, 'http://localhost:8080/menu-images/orange-juice.jpg', '橙子现榨，保留清新果香，一杯约350毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (31, '珍珠奶茶', 7, 15, 'http://localhost:8080/menu-images/bubble-tea.jpg', '醇香奶茶配软糯珍珠，一杯约450毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (32, '抹茶拿铁', 7, 18, 'http://localhost:8080/menu-images/matcha-latte.jpg', '抹茶与牛奶交融，茶香清新，一杯约350毫升。', 0, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (33, '香酥鸡肉沙拉', 3, 32, 'http://localhost:8080/menu-images/chicken-salad.jpg', '鸡肉搭配番茄、生菜与彩椒，荤素搭配。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (34, '莓果芝士蛋糕', 8, 22, 'http://localhost:8080/menu-images/berry-cheesecake.jpg', '细腻芝士搭配莓果，一份单人切块。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (35, '缤纷鲜果杯', 8, 20, 'http://localhost:8080/menu-images/fruit-salad.jpg', '奇异果、菠萝与草莓搭配，一份约250克，清甜解腻。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (36, '冰拿铁', 7, 18, 'http://localhost:8080/menu-images/iced-latte.jpg', '浓缩咖啡与牛奶融合，冰爽顺滑，一杯约350毫升。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (37, '三色糯米大福', 8, 24, 'http://localhost:8080/menu-images/mochi.jpg', '三色糯米大福组合，软糯香甜，一份3只。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (38, '奶油雪媚娘拼盘', 8, 26, 'http://localhost:8080/menu-images/strawberry-mochi.jpg', '软糯外皮搭配奶油夹心，一份3只。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (39, '椰香鲜果谷物碗', 8, 25, 'http://localhost:8080/menu-images/fruit-granola.jpg', '酸奶搭配鲜果、椰片与谷物，清甜丰富，适合餐后分享。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (40, '藜麦烤时蔬', 3, 28, 'http://localhost:8080/menu-images/broccoli-mix.jpg', '藜麦搭配烤西兰花、菜花与彩蔬，清爽饱腹。', 1, DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1);
