INSERT INTO `setmeal` (`id`, `category_id`, `name`, `price`, `status`, `description`, `image`, `create_time`, `update_time`, `create_user`, `update_user`) VALUES
  (1, 9, '麻婆豆腐工作餐', 35, 1, '麻婆豆腐、现蒸白米饭、冰爽可乐。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-mapo-lunch.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
