  (3, 9, '红烧肉满足餐', 49, 1, '秘制红烧肉、现蒸白米饭、芝麻拍黄瓜。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-pork-lunch.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (4, 9, '牛肉面暖心餐', 45, 1, '红烧牛肉面、香脆素春卷。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-noodle-lunch.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (5, 9, '香酥鸡饭畅饮餐', 32, 1, '香酥鸡块饭、冰爽可乐。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-chicken-lunch.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (6, 9, '鸡肉轻食元气餐', 42, 1, '香酥鸡肉沙拉、鲜榨橙汁。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-salad-lunch.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (7, 10, '川味下饭双人餐', 88, 1, '宫保鸡丁、干香辣子鸡、现蒸白米饭×2、芝麻拍黄瓜。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-sichuan-duo.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (8, 10, '家常好味双人餐', 85, 1, '秘制红烧肉、香辣烤茄子、现蒸白米饭×2、冰爽可乐×2。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-home-duo.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (9, 10, '饭面招牌双人餐', 82, 1, '红烧牛肉面、香酥鸡块饭、香脆素春卷、手作柠檬茶×2。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-noodle-duo.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (10, 10, '追剧小食分享餐', 65, 1, '香酥炸鸡翅、金黄薯条、香脆素春卷、冰爽可乐×2。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-snack-party.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (11, 11, '合家欢四人餐', 118, 1, '宫保鸡丁、秘制红烧肉、蒜香空心菜、现蒸白米饭×4、冰爽可乐×4。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-family-feast.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1),
  (12, 11, '周末聚会四人餐', 168, 0, '糖醋咕噜肉、干香辣子鸡、干煸四季豆、现蒸白米饭×4、香酥炸鸡翅、手作柠檬茶×4。套餐封面按所含商品拼图展示。', 'http://localhost:8080/menu-images/setmeal-weekend-feast.jpg', DATE_SUB(@demo_now, INTERVAL 60 DAY), DATE_SUB(@demo_now, INTERVAL 60 MINUTE), 1, 1);
